// MIDI Conductor 0.7.1 for firmware 5.52 (DOOM OS 0.7.2 359C): the patcher. A page loads it with
//   <div id="patcher"></div> <script src="conductor-patcher.js"></script>
// Adapted from the DOOM OS patcher, MIT licence, Quintus Oostendorp (see NOTICE.md).
window.CONDUCTOR_RELEASE = {"name": "MIDI Conductor", "version": "0.7.1", "channel": "", "release": "0.7.1", "base": "DOOM OS 0.7.2 359C", "released": "2026-11-01", "firmware": [{"version": "5.52", "stock_sha256": "4a3d67711e14dcc97d50249a4eee7dd6df0251a2f37757cbbe2556c233730d80", "patched_sha256": "84d63d9d1de9cfd462089e8ecb61fbcf16cffc94213e834306421eecba76798b", "patched_size": 3387120}]};
window.CONDUCTOR_PATCH = "";
'use strict';

// SHA-256, so the page needs no crypto API and works from a file:// URL in any browser.
function sha256(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
  const total = bytes.length;
  const padded = new Uint8Array((((total + 8) >> 6) + 1) << 6);
  padded.set(bytes);
  padded[total] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor(total / 0x20000000), false);
  view.setUint32(padded.length - 4, (total << 3) >>> 0, false);
  const w = new Uint32Array(64);
  const rot = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < padded.length; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = view.getUint32(i + t * 4, false);
    for (let t = 16; t < 64; t++) {
      const a = w[t - 15], b = w[t - 2];
      const s0 = rot(a, 7) ^ rot(a, 18) ^ (a >>> 3);
      const s1 = rot(b, 17) ^ rot(b, 19) ^ (b >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (let t = 0; t < 64; t++) {
      const S1 = rot(e, 6) ^ rot(e, 11) ^ rot(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rot(a, 2) ^ rot(a, 13) ^ rot(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0;
  }
  const out = new Uint8Array(32);
  new DataView(out.buffer).setUint32(0, h0, false);
  [h1, h2, h3, h4, h5, h6, h7].forEach((v, i) => new DataView(out.buffer).setUint32(4 + i * 4, v, false));
  return out;
}

function hex(bytes) {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s;
}

function sameBytes(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

// Every firmware the container can patch: [{label, source, target, size}], digests as hex.
function patchVersions(container) {
  const view = new DataView(container.buffer, container.byteOffset, container.byteLength);
  const magic = String.fromCharCode(...container.subarray(0, 8));
  if (magic !== 'DOOMPTCH') throw new Error('this file is not a DOOM OS patch');
  if (view.getUint16(8, true) !== 1) throw new Error('this patch was made for a newer patcher');
  const count = view.getUint16(10, true);
  const out = [];
  for (let i = 0; i < count; i++) {
    const at = 12 + i * 96;
    const label = String.fromCharCode(...container.subarray(at, at + 16)).replace(/\0+$/, '');
    out.push({
      label,
      source: hex(container.subarray(at + 16, at + 48)),
      target: hex(container.subarray(at + 48, at + 80)),
      size: view.getUint32(at + 80, true),
      records: view.getUint32(at + 84, true),
      recordsAt: view.getUint32(at + 88, true),
      dataAt: view.getUint32(at + 92, true),
    });
  }
  return out;
}

// The firmware file in, the DOOM OS firmware out. Throws when the input is not a firmware this
// patch was made for, or when the result is not what the patch says it should be.
function applyPatch(container, source) {
  const digest = hex(sha256(source));
  const entry = patchVersions(container).find(v => v.source === digest);
  if (!entry) {
    const err = new Error('unsupported firmware');
    err.digest = digest;
    err.supported = patchVersions(container);
    throw err;
  }
  const view = new DataView(container.buffer, container.byteOffset, container.byteLength);
  const out = new Uint8Array(entry.size);
  out.set(source.subarray(0, Math.min(source.length, entry.size)));
  let read = entry.dataAt;
  for (let i = 0; i < entry.records; i++) {
    const rec = entry.recordsAt + i * 12;
    const at = view.getUint32(rec, true);
    const len = view.getUint32(rec + 4, true);
    const where = view.getUint32(rec + 8, true);
    if (where === 0xFFFFFFFF) {
      out.set(container.subarray(read, read + len), at);
      read += len;
    } else {
      out.set(source.subarray(where, where + len), at);
    }
  }
  const made = hex(sha256(out));
  if (made !== entry.target) {
    throw new Error('the patched firmware came out wrong (' + made.slice(0, 12) + ' instead of '
                    + entry.target.slice(0, 12) + '); do not put this on the SP');
  }
  return { label: entry.label, bytes: out, digest: made };
}

// base64 without a DOM: the page inlines its patch as text.
function fromBase64(text) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const clean = text.replace(/[^A-Za-z0-9+/]/g, '');
  const pad = text.endsWith('==') ? 2 : text.endsWith('=') ? 1 : 0;
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let acc = 0, bits = 0, o = 0;
  for (const ch of clean) {
    acc = (acc << 6) | chars.indexOf(ch);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (o < out.length) out[o++] = (acc >> bits) & 0xff;
    }
  }
  return out;
}

if (typeof module === 'object' && module.exports) {
  module.exports = { applyPatch, patchVersions, sha256, hex, fromBase64, sameBytes };
}
// ---- the page ----
// The patcher as a page shows it: it draws the file panel into <div id="conductor-patcher"></div>,
// wires the patch button and the download link, and writes the release's version, build, firmware
// and date into the elements marked `data-doomos`. The styling is the page's: the panel carries the
// classes `panel`, `drop`, `status`, `hashes`, `copy`, `note`, `actions`, `btn` and `state`.
//
// Each file it vouches for it shows by its SHA-256: the owner's Roland firmware once it is
// recognised, and the DOOM OS firmware once it is made, both the digests checksums.txt lists.
(function () {
  function start() {
    const release = window.CONDUCTOR_RELEASE;
    const labels = release.firmware.map(f => f.version);
    const [y, m, d] = release.released.split('-').map(Number);
    const facts = {
      version: release.version + ' ' + release.channel,
      build: release.build,
      firmware: labels.join(' / '),
      'firmware-list': labels.join(' and '),
      released: new Date(Date.UTC(y, m - 1, d)).toLocaleDateString('en-GB',
        { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }),
    };
    for (const el of document.querySelectorAll('[data-release]')) {
      const value = facts[el.dataset.release];
      if (value !== undefined) el.textContent = value;
    }

    const host = document.getElementById('patcher');
    if (!host) return;
    host.innerHTML =
      '<div class="panel">' +
      '<input type="file" id="file" accept=".bin,application/octet-stream" hidden>' +
      '<div class="drop" id="drop" role="button" tabindex="0" aria-describedby="status">' +
      '<p class="big" id="dropBig">Drop the SP404MKII_APP1.bin here</p>' +
      '<p class="small" id="dropSmall">or click to choose</p>' +
      '</div>' +
      '<p class="status" id="status" role="status">Ready. No file loaded yet.</p>' +
      '<dl class="hashes" id="hashes" hidden></dl>' +
      '<div class="actions">' +
      '<button type="button" class="btn" id="patch" disabled>Patch firmware</button>' +
      '<a class="btn" id="download" download="SP404MKII_APP1.bin" hidden>Download patched firmware ↓</a>' +
      '<button type="button" class="btn ghost" id="reset" hidden>New file</button>' +
      '<span class="state" id="state">Waiting for file</span>' +
      '</div>' +
      '</div>';

    const $ = id => document.getElementById(id);
    const input = $('file'), drop = $('drop'), big = $('dropBig'), small = $('dropSmall');
    const status = $('status'), state = $('state'), hashes = $('hashes');
    const patchBtn = $('patch'), download = $('download'), reset = $('reset');
    const container = fromBase64(window.CONDUCTOR_PATCH);
    const versions = patchVersions(container);
    const supported = versions.map(v => v.label).join(' and ');
    let source = null, url = null;

    function say(text, kind) {
      status.textContent = text;
      status.className = 'status' + (kind ? ' ' + kind : '');
    }

    // A file vouched for: what it is, and its SHA-256 to compare or copy.
    function vouch(what, digest) {
      const row = document.createElement('div');
      row.innerHTML = '<dt></dt><dd><code></code><button type="button" class="copy">Copy</button></dd>';
      row.querySelector('dt').textContent = '\u2713 ' + what;
      row.querySelector('code').textContent = digest;
      const copy = row.querySelector('.copy');
      copy.addEventListener('click', () => {
        if (navigator.clipboard) navigator.clipboard.writeText(digest).then(() => { copy.textContent = 'Copied'; });
      });
      let note = hashes.querySelector('.note');
      if (!note) {
        note = document.createElement('p');
        note.className = 'note';
        note.textContent = 'SHA-256, as the release lists them in its checksums.txt.';
      }
      hashes.append(row, note);
      hashes.hidden = false;
    }

    function size(bytes) {
      return bytes > 1048576 ? (bytes / 1048576).toFixed(1) + ' MB' : Math.round(bytes / 1024) + ' KB';
    }

    function clear() {
      if (url) URL.revokeObjectURL(url);
      url = null;
      source = null;
      download.hidden = true;
      reset.hidden = true;
      hashes.hidden = true;
      hashes.textContent = '';
      patchBtn.hidden = false;
      patchBtn.disabled = true;
      patchBtn.textContent = 'Patch firmware';
      drop.classList.remove('bad');
    }

    function refuse(text) {
      say(text, 'bad');
      state.textContent = 'Aborted';
      drop.classList.add('bad');
      reset.hidden = false;
    }

    async function take(file) {
      if (!file) return;
      clear();
      big.textContent = file.name;
      big.classList.add('file');
      small.textContent = size(file.size) + ' · click to replace';
      if (/\.zip$/i.test(file.name)) {
        refuse('That is the zip from Roland. Unzip it first, and choose the SP404MKII_APP1.bin inside.');
        return;
      }
      say('Checking the file …');
      state.textContent = 'Checking';
      await new Promise(r => setTimeout(r, 20));
      const bytes = new Uint8Array(await file.arrayBuffer());
      const digest = hex(sha256(bytes));
      const match = versions.find(v => v.source === digest);
      if (!match) {
        if (/APP0/i.test(file.name)) {
          refuse('This is SP404MKII_APP0.bin. You need SP404MKII_APP1.bin, from the same folder.');
        } else {
          refuse('This is not a firmware file this patcher knows. It is built for firmware '
                 + supported + ': download the system update from Roland and choose the '
                 + 'SP404MKII_APP1.bin inside.');
        }
        return;
      }
      source = bytes;
      say('Firmware ' + match.label + ' detected. Ready to patch.', 'ok');
      vouch('Roland firmware ' + match.label + ', the official file', digest);
      state.textContent = 'Ready';
      patchBtn.disabled = false;
    }

    async function patch() {
      if (!source) return;
      patchBtn.disabled = true;
      patchBtn.textContent = 'Patching …';
      state.textContent = 'Patching';
      await new Promise(r => setTimeout(r, 20));
      try {
        const result = applyPatch(container, source);
        url = URL.createObjectURL(new Blob([result.bytes], { type: 'application/octet-stream' }));
        download.href = url;
        download.hidden = false;
        reset.hidden = false;
        patchBtn.hidden = true;
        say('Done. MIDI Conductor has been patched into firmware ' + result.label + '. '
            + 'Download it and keep the name SP404MKII_APP1.bin.', 'ok');
        vouch('MIDI Conductor ' + release.release + ' (' + release.base + '), the published image', result.digest);
        state.textContent = 'Complete';
      } catch (err) {
        patchBtn.textContent = 'Patch firmware';
        refuse(err.message);
      }
    }

    function again() {
      clear();
      input.value = '';
      big.textContent = 'Drop the SP404MKII_APP1.bin here';
      big.classList.remove('file');
      small.textContent = 'or click to choose';
      say('Ready. No file loaded yet.');
      state.textContent = 'Waiting for file';
    }

    drop.addEventListener('click', () => input.click());
    drop.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); input.click(); }
    });
    drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('over'); });
    drop.addEventListener('dragleave', () => drop.classList.remove('over'));
    drop.addEventListener('drop', e => {
      e.preventDefault();
      drop.classList.remove('over');
      take(e.dataTransfer.files && e.dataTransfer.files[0]);
    });
    // a file dropped beside the panel is not opened by the browser in place of the page
    window.addEventListener('dragover', e => e.preventDefault());
    window.addEventListener('drop', e => e.preventDefault());
    input.addEventListener('change', () => take(input.files && input.files[0]));
    patchBtn.addEventListener('click', patch);
    reset.addEventListener('click', again);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
